parameters.jsCode:
const items = $input.all();
const tweets = items[0].json.data || [];
const resultCount = items[0].json.meta?.result_count || 0;

// Threshold: more than 10 crisis-related mentions in 15 min
const CRISIS_THRESHOLD = 10;
const isCrisis = resultCount >= CRISIS_THRESHOLD;

const topKeywords = {};
for (const tweet of tweets) {
  const crisisWords = ['scam','fraud','outage','down','hack','breach','crisis','boycott','lawsuit'];
  for (const word of crisisWords) {
    if (tweet.text.toLowerCase().includes(word)) {
      topKeywords[word] = (topKeywords[word] || 0) + 1;
    }
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    mention_count: resultCount,
    is_crisis: isCrisis,
    severity: resultCount >= 50 ? 'CRITICAL' : resultCount >= 20 ? 'HIGH' : resultCount >= 10 ? 'MEDIUM' : 'LOW',
    top_keywords: JSON.stringify(topKeywords),
    sample_tweets: tweets.slice(0, 5).map(t => t.text).join(' | ')
  }
}];

